using System.Collections.Concurrent;
using System.Text.Json;
namespace ONEXTweaks.WidgetBridge;
internal static class ControllerOemGestureNativeVerification
{
 internal static async Task<int> Run(string file)
 {
  int checks=0;ControllerVirtualPad? pad=null;var original=ControllerNative.Slots();void Check(bool value,string message){checks++;if(!value)throw new IOException(message);}
  try
  {
   Check(original.SequenceEqual(new[]{0})&&ControllerNative.Read(0,out var frame)&&ControllerNative.Neutral(frame),"Protect owner controller before synthetic OEM test");using var window=new ControllerTestWindow();window.RequireForeground();using var emitter=new ControllerInputEmitter();using var source=new ControllerOemRawInput();var signals=new ConcurrentQueue<ControllerOemSignal>();source.ActionSignal+=signals.Enqueue;
   ControllerOemPolicy current=new ControllerOemPolicy(new(){{"M1",new("gamepad","A")}},new(){{"M1",new(true,150,new("gamepad","B"))}}).Validate();source.ConfigureGestures(()=>Volatile.Read(ref current));for(int n=0;n<100&&!source.Listening;n++)await Task.Delay(10);Check(source.Listening,"Synthetic OEM listener did not initialize");source.FirmwareAliases(true);pad=new ControllerVirtualPad(0,false);var translator=new ControllerTranslator();ushort single=(ushort)(1<<4),twice=(ushort)(1<<(4+6));
   async Task Mask(ushort expected){for(int n=0;n<150;n++){if(source.RemapMask==expected)return;await Task.Delay(5);}throw new IOException("Synthetic OEM action mask mismatch");}
   async Task Pad(ushort mask,ushort buttons){await Mask(mask);var output=translator.Translate(new(Oem:source.RemapMask),new ControllerPolicy(Oem:Volatile.Read(ref current)).Validate());pad.Submit(output.Pad,output.Guide);for(int n=0;n<100;n++){if(ControllerNative.Read(pad.Slot,out var observed)&&observed.Buttons==buttons){Check(true,"Real VIIPER readback");return;}await Task.Delay(5);}throw new IOException("Gesture did not reach actual VIIPER state");}
   source.FromHook(new("M1",true));await Task.Delay(20);Check(source.RemapMask==0,"First pending press leaked output");source.FromHook(new("M1",false));await Pad(single,4096);await Mask(0);pad.Submit(new());Check(signals.Count(value=>value.Button=="M1"&&value.Pressed)==1&&!signals.Any(value=>value.Button=="M1:Double"),"Single synthetic alias dispatch wrong");
   while(signals.TryDequeue(out _)){}source.FromHook(new("M1",true));await Task.Delay(20);source.FromHook(new("M1",false));await Task.Delay(25);source.FromHook(new("M1",true));await Pad(twice,8192);source.FromHook(new("M1",false));await Mask(0);pad.Submit(new());Check(signals.Count(value=>value.Button=="M1:Double"&&value.Pressed)==1&&!signals.Any(value=>value.Button=="M1"&&value.Pressed),"Single fired alongside synthetic double");
   window.RequireForeground();Check(!ControllerTestWindow.IsHeld(90),"Protect owner held Z key");Volatile.Write(ref current,new ControllerOemPolicy(new(){{"M1",new("keyboard",Keys:[90])}}).Validate());source.RefreshGestures();source.FromHook(new("M1",true));await Mask(single);emitter.Apply(translator.Translate(new(Oem:source.RemapMask),new ControllerPolicy(Oem:Volatile.Read(ref current)).Validate()),0);await Task.Delay(50);Check(ControllerTestWindow.IsHeld(90),"Synthetic OEM did not hold actual keyboard output");Volatile.Write(ref current,current with{});source.RefreshGestures();await Mask(0);window.RequireForeground();emitter.Apply(translator.Translate(new(),new ControllerPolicy(Oem:current).Validate()),0);await Task.Delay(50);Check(!ControllerTestWindow.IsHeld(90)&&signals.Any(value=>value.Button=="M1"&&value.Cancelled),"Profile replacement failed to cancel held real key");source.FromHook(new("M1",false));await Task.Delay(40);
   Volatile.Write(ref current,new ControllerOemPolicy(new(){{"M1",new("gamepad","A")}},new(){{"M1",new(true,150,new("gamepad","B"))}}).Validate());source.RefreshGestures();while(signals.TryDequeue(out _)){}source.FromHook(new("M1",true));await Task.Delay(20);source.FromHook(new("M1",false));await Task.Delay(20);source.FirmwareAliases(false);await Task.Delay(240);Check(source.RemapMask==0&&!signals.Any(value=>value.Pressed),"Disable fired a pending alias action");source.FromHook(new("M1",false));await Task.Delay(30);Volatile.Write(ref current,new ControllerOemPolicy(new(){{"M1",new("gamepad","A")}}).Validate());source.FirmwareAliases(true);source.RefreshGestures();source.FromHook(new("M1",true));Volatile.Write(ref current,current with{});source.RefreshGestures();await Task.Delay(40);Check(source.RemapMask==0,"Deferred pre-profile down escaped transition");source.FromHook(new("M1",false));await Task.Delay(30);source.FromHook(new("M1",true));await Mask(single);Check(source.RemapMask==single,"Fresh source press did not rearm after transition");source.FirmwareAliases(false);source.FromHook(new("M1",false));pad.Dispose();pad=null;Check(ControllerNative.Slots().SequenceEqual(original),"Temporary VIIPER device not removed");
   await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=true,checks,syntheticOemFromHook=true,actualRawInputWorker=true,actualViiperReadback=true,actualOwnWindowKeyboardHoldRelease=true,profileCancellation=true,disableCancellation=true,deferredGenerationCancellation=true,physicalOwnerInputTested=false,firmwareWrites=0,productionCaptureEnabled=false,temporaryVirtualRemoved=true,settingsWrites=0},Backend.Program.Json));return 0;
  }catch(Exception error){await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=false,checks,error=error.Message},Backend.Program.Json));return 2;}
  finally{try{pad?.Dispose();}catch{}}
 }
}
